$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $true
$projectRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
docker build -t durevo-native-tests:local (Join-Path $projectRoot 'native')
if ($LASTEXITCODE -ne 0) { throw 'Native test image build failed.' }
docker run --rm --mount "type=bind,source=$projectRoot,target=/source,readonly" durevo-native-tests:local sh -c 'set -eu; mkdir -p /tmp/durevo/tests; cp -r /source/src /source/third-party /source/Directory.Build.props /source/global.json /source/NuGet.Config /tmp/durevo/; cp -r /source/tests/Durevo.Tests /source/tests/Durevo.Fixture /tmp/durevo/tests/; cd /tmp/durevo; gcc --version; dotnet restore tests/Durevo.Tests --locked-mode; dotnet build tests/Durevo.Tests -c Release --no-restore; gcc -std=c11 -O2 -Wall -Wextra -Werror -fPIC -fvisibility=hidden -shared /source/native/durevo_encrypted.c -lcrypto -o tests/Durevo.Tests/bin/Release/net10.0/libdurevo_vm.so; dotnet build src/Durevo.Cli -c Release; dotnet run --project tests/Durevo.Tests -c Release --no-build -- --native --release-cli /tmp/durevo/src/Durevo.Cli/bin/Release/net10.0/Durevo.Cli.dll; gcc -std=c11 -O1 -g -Wall -Wextra -Werror -fsanitize=address,undefined -fno-omit-frame-pointer /source/native/fuzz_smoke.c -o /tmp/durevo-fuzz; /tmp/durevo-fuzz; gcc -std=c11 -O1 -g -Wall -Wextra -Werror -fsanitize=address,undefined -fno-omit-frame-pointer /source/native/encrypted_fuzz_smoke.c -lcrypto -o /tmp/durevo-encrypted-fuzz; /tmp/durevo-encrypted-fuzz; sh /source/scripts/test-native-interposition.sh; gcc -std=c11 -O1 -g -Wall -Wextra -Werror -fsanitize=address,undefined -fno-omit-frame-pointer /source/native/string_fuzz_smoke.c -o /tmp/durevo-string-fuzz; /tmp/durevo-string-fuzz'
if ($LASTEXITCODE -ne 0) { throw "Native Linux test failed: $LASTEXITCODE" }
